export function summarizeEvents(events) {
  const summary = {
    total: events.length,
    byLevel: {
      info: 0,
      warn: 0,
      error: 0
    },
    byService: {},
    averageDurationMs: 0,
    errors: []
  };

  let durationSum = 0;
  let durationCount = 0;

  for (const event of events) {
    if (summary.byLevel[event.level] !== undefined) {
      summary.byLevel[event.level]++;
    } else {
      summary.byLevel[event.level] = 1;
    }

    summary.byService[event.service] = (summary.byService[event.service] || 0) + 1;

    if (event.durationMs !== undefined) {
      durationSum += event.durationMs;
      durationCount++;
    }

    if (event.level === 'error') {
      summary.errors.push({
        timestamp: event.timestamp,
        service: event.service,
        message: event.message
      });
    }
  }

  summary.averageDurationMs = durationCount > 0 ? durationSum / durationCount : 0;

  return summary;
}

